import{_ as a,o as i,c as d,ao as r}from"./chunks/framework.DHldJ08f.js";const g=JSON.parse('{"title":"Drawer, WIP","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/messaging/drawer.md","filePath":"generated/grindr-api/messaging/drawer.md"}'),o={name:"grindr-api/messaging/drawer.md"};function s(l,e,n,t,p,c){return i(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="drawer-wip" tabindex="-1">Drawer, WIP <a class="header-anchor" href="#drawer-wip" aria-label="Permalink to “Drawer, WIP”">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This page is a work in progress. Endpoints below haven&#39;t been fully researched.</p></div><h2 id="get-media-in-drawer" tabindex="-1">Get media in drawer <a class="header-anchor" href="#get-media-in-drawer" aria-label="Permalink to “Get media in drawer”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v4/chat/media/drawer</span></span></code></pre></div><p>Response:</p><p>Array of <a href="/grindr-api/messaging/drawer#drawermedia">DrawerMedia</a>.</p><h2 id="get-media-in-drawer-for-a-conversation" tabindex="-1">Get media in drawer for a conversation <a class="header-anchor" href="#get-media-in-drawer-for-a-conversation" aria-label="Permalink to “Get media in drawer for a conversation”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /v4/chat/media/drawer/{conversationId}</span></span></code></pre></div><p>Response:</p><p>Array of <a href="/grindr-api/messaging/drawer#drawermedia">DrawerMedia</a>.</p><h2 id="add-media-to-drawer" tabindex="-1">Add media to drawer <a class="header-anchor" href="#add-media-to-drawer" aria-label="Permalink to “Add media to drawer”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Takes a <code>mediaId</code> from <a href="/grindr-api/messaging/drawer#upload-media">uploading</a>. Videos are accepted and listed as <code>video/mp4</code>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PUT /v4/chat/media/drawer/{mediaId}</span></span></code></pre></div><p>Response:</p><p>Empty.</p><p>Errors:</p><ul><li><code>500</code> — Repeated requests cause 500 HTTP status &quot;Internal Error&quot;.</li></ul><h2 id="delete-media-from-drawer" tabindex="-1">Delete media from drawer <a class="header-anchor" href="#delete-media-from-drawer" aria-label="Permalink to “Delete media from drawer”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Removes the item from the drawer. Album copies made with <a href="/grindr-api/messaging/albums#add-drawer-media-to-an-album">Add drawer media to an album</a> are separate files and stay. The CDN may keep serving the deleted file&#39;s signed url from cache.</p><p>Repeated requests are completed without errors.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DELETE /v4/chat/media/drawer/{mediaId}</span></span></code></pre></div><p>Response:</p><p>Empty with HTTP status 202.</p><h2 id="upload-media" tabindex="-1">Upload media <a class="header-anchor" href="#upload-media" aria-label="Permalink to “Upload media”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Requires a correct <code>Content-Type</code>. Set <code>length</code> for audio and video, and <code>looping</code> for video. Videos are uploaded as <code>video/mp4</code>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v5/chat/media/upload</span></span></code></pre></div><p>Query:</p><ul><li><code>length</code> — long integer, Duration in milliseconds., optional</li><li><code>looping</code> — boolean, optional</li><li><code>takenOnGrindr</code> — boolean, Media captured with the in-app camera.</li></ul><p>Body:</p><p>Binary file.</p><p>Response:</p><ul><li><code>mediaId</code> — long integer</li><li><code>url</code> — URL</li><li><code>mediaHash</code> — string, See <a href="/grindr-api/media/public-cdn-files#profile-images">Media -&gt; Public CDN files -&gt; Profile Images</a></li></ul><h2 id="upload-media-signed" tabindex="-1">Upload media (signed) <a class="header-anchor" href="#upload-media-signed" aria-label="Permalink to “Upload media (signed)”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Signed version of the unsigned <a href="/grindr-api/messaging/drawer#upload-media">Upload media</a>. A correct <code>Content-Type</code> request header is required, and the request must carry a valid device-key signature over the raw request body; see <a href="/grindr-api/security-headers#device-key-upload-signing">Security headers -&gt; Device-key upload signing</a>. <code>length</code> and <code>looping</code> are never sent here. All media uploaded through this endpoint are marked as &quot;Taken on Grindr&quot; server-side.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v6/chat/media/upload</span></span></code></pre></div><p>Query (optional):</p><ul><li><code>length</code> — long integer, optional</li><li><code>looping</code> — boolean, optional</li></ul><p>Headers:</p><ul><li><code>X-Key-Id</code> — base64url (no padding) <code>SHA-256</code> of the device key SPKI — the <code>keyId</code> from <a href="/grindr-api/media/device-keys#register-device-key">Register device key</a>.</li><li><code>X-Sig</code> — base64url (no padding) DER ECDSA-P256-SHA256 signature over the UTF-8 string <code>bodyHash|timestamp|userId|androidId|nonce</code>. See <a href="/grindr-api/security-headers#device-key-upload-signing">Security headers -&gt; Device-key upload signing</a>.</li><li><code>X-Timestamp</code> — Signing time as Unix epoch milliseconds (decimal string); must equal the <code>timestamp</code> inside the signed string.</li><li><code>X-Nonce</code> — base64url (no padding) of 32 random bytes, unique per request; must equal the <code>nonce</code> inside the signed string.</li></ul><p>Body:</p><p>Binary file.</p><p>Response:</p><ul><li><code>mediaId</code> — long integer</li><li><code>url</code> — URL</li><li><code>mediaHash</code> — string, See <a href="/grindr-api/media/public-cdn-files#profile-images">Media -&gt; Public CDN files -&gt; Profile Images</a></li></ul><p>Errors:</p><ul><li><code>422</code> — Media rejected by moderation.</li><li><code>4xx</code> — Signature rejected; see <code>UploadSigningErrorResponse</code> (<code>timestamp_drift</code> / <code>nonce_replayed</code>).</li></ul><h2 id="drawermedia" tabindex="-1">DrawerMedia <a class="header-anchor" href="#drawermedia" aria-label="Permalink to “DrawerMedia”">​</a></h2><ul><li><code>id</code> — long integer</li><li><code>url</code> — URL</li><li><code>contentType</code> — string</li><li><code>createdTs</code> — unix timestamp in milliseconds</li><li><code>used</code> — boolean</li><li><code>takenOnGrindr</code> — boolean</li></ul><h2 id="mediauploadresponse" tabindex="-1">MediaUploadResponse <a class="header-anchor" href="#mediauploadresponse" aria-label="Permalink to “MediaUploadResponse”">​</a></h2><ul><li><code>mediaId</code> — long integer</li><li><code>url</code> — URL</li><li><code>mediaHash</code> — string, See <a href="/grindr-api/media/public-cdn-files#profile-images">Media -&gt; Public CDN files -&gt; Profile Images</a></li></ul><h2 id="mediauploadproblemresponse" tabindex="-1">MediaUploadProblemResponse <a class="header-anchor" href="#mediauploadproblemresponse" aria-label="Permalink to “MediaUploadProblemResponse”">​</a></h2><p>RFC-7807 problem body returned on a <code>422</code> when uploaded media is blocked by moderation.</p><ul><li><code>type</code> — string, error URN — <code>urn:gr:err:banned_image</code> or <code>urn:gr:err:banned_video</code>, optional</li><li><code>title</code> — string, optional</li><li><code>status</code> — integer, <code>422</code>, optional</li><li><code>traceId</code> — string, optional</li></ul>',58)])])}const u=a(o,[["render",s]]);export{g as __pageData,u as default};
